import"./chunk-VC46IEJQ.js";var e=(a,o,s,l,r,n,h,i,t)=>({name:{en:a[0],zh:a[1]},desc:{en:o[0],zh:o[1]},tour:{en:s[0],zh:s[1]},...t?{spoiler:{en:t[0],zh:t[1]}}:{},source:{confidence:l,refs:r,book:{en:n[0],zh:n[1]},unknown:{en:h[0],zh:h[1]},interpretation:{en:i[0],zh:i[1]}}}),d={id:"the-eyrie",intro:{en:"A small white castle clings to a shoulder of the Giant's Lance, high above the Vale. Visitors ride mules up from the Gates of the Moon past three waycastles, Stone, Snow and Sky, then climb the last stretch through the rock itself.",zh:"\u4E00\u5EA7\u5C0F\u5DE7\u7684\u767D\u8272\u57CE\u5821\u7D27\u8D34\u5728\u5DE8\u4EBA\u4E4B\u67AA\u7684\u5C71\u80A9\u4E0A\uFF0C\u9AD8\u9AD8\u4FEF\u77B0\u827E\u6797\u8C37\u3002\u8BBF\u5BA2\u4ECE\u6708\u95E8\u5821\u9A91\u9AA1\u4E0A\u5C71\uFF0C\u4F9D\u6B21\u7ECF\u8FC7\u77F3\u5821\u3001\u96EA\u5821\u4E0E\u5929\u5821\u4E09\u5EA7\u8DEF\u5821\uFF0C\u6700\u540E\u4E00\u6BB5\u5219\u8981\u5728\u5C71\u5CA9\u4E4B\u4E2D\u6500\u722C\u800C\u4E0A\u3002"},notes:{en:"From the novels: the Gates of the Moon at the foot, the mule path past Stone, Snow and Sky, the chimney climb and supply winches above Sky, a small castle of seven slender white towers, the marble High Hall with its Moon Door, the open sky cells, the waterfall called Alyssa's Tears and a small garden meant as a godswood. Invented here: the mountain's shape and scale, the number and pitch of switchbacks, every building position and all architectural detail.",zh:"\u51FA\u81EA\u5C0F\u8BF4\uFF1A\u5C71\u811A\u7684\u6708\u95E8\u5821\uFF0C\u9014\u7ECF\u77F3\u5821\u3001\u96EA\u5821\u3001\u5929\u5821\u7684\u9AA1\u9053\uFF0C\u5929\u5821\u4E4B\u4E0A\u7684\u5CA9\u7F1D\u6500\u9053\u4E0E\u8FD0\u8D27\u7EDE\u76D8\uFF0C\u7531\u4E03\u5EA7\u7EC6\u9AD8\u767D\u5854\u7EC4\u6210\u7684\u5C0F\u57CE\u5821\uFF0C\u8BBE\u6709\u6708\u95E8\u7684\u5927\u7406\u77F3\u9AD8\u5385\uFF0C\u655E\u5F00\u7684\u5929\u7262\uFF0C\u540D\u4E3A\u201C\u827E\u4E3D\u838E\u4E4B\u6CEA\u201D\u7684\u7011\u5E03\uFF0C\u4EE5\u53CA\u4E00\u5EA7\u672C\u60F3\u8F9F\u4F5C\u795E\u6728\u6797\u7684\u5C0F\u82B1\u56ED\u3002\u672C\u573A\u666F\u81EA\u884C\u8BBE\u8BA1\uFF1A\u5C71\u4F53\u5F62\u6001\u4E0E\u5C3A\u5EA6\u3001\u4E4B\u5B57\u5F62\u5C71\u8DEF\u7684\u6298\u6570\u4E0E\u5761\u5EA6\u3001\u5404\u5EFA\u7B51\u4F4D\u7F6E\u53CA\u4E00\u5207\u5EFA\u7B51\u7EC6\u8282\u3002"},tour:["the-vale","gates-of-the-moon","stone-waycastle","snow-waycastle","sky-waycastle","alyssas-tears","giants-lance","eyrie-towers","high-hall","moon-door","sky-cells","eyrie-godswood"],sources:[{ref:"agot",checked:"memory",note:{en:"Catelyn's ascent and Tyrion's captivity: the waycastles, the High Hall, the sky cells and the garden duel; recalled, not re-read.",zh:"\u51EF\u7279\u7433\u767B\u5C71\u4E0E\u63D0\u5229\u6602\u88AB\u56DA\uFF1A\u8DEF\u5821\u3001\u9AD8\u5385\u3001\u5929\u7262\u4E0E\u82B1\u56ED\u4E2D\u7684\u51B3\u6597\uFF1B\u51ED\u8BB0\u5FC6\uFF0C\u672A\u91CD\u8BFB\u3002"}},{ref:"asos",checked:"memory",note:{en:"Sansa's time at the Eyrie, the snowy garden and the High Hall; recalled.",zh:"\u73CA\u838E\u5728\u9E70\u5DE2\u57CE\u7684\u65E5\u5B50\u3001\u79EF\u96EA\u7684\u82B1\u56ED\u4E0E\u9AD8\u5385\uFF1B\u51ED\u8BB0\u5FC6\u3002"}},{ref:"awoiaf",checked:"search-snippet",note:{en:"Search summaries of the wiki and concordance: Sky is a crescent wall of unmortared stone some 600 ft below the Eyrie; a chimney with handholds leads up, while winches with iron chains haul baskets; the garden was meant as a godswood but the soil is too thin for a weirwood, and a statue of a weeping woman stands in it. Pages not fetched.",zh:"\u7EF4\u57FA\u4E0E\u8BCD\u6761\u7D22\u5F15\u7684\u641C\u7D22\u6458\u8981\uFF1A\u5929\u5821\u662F\u4E00\u9053\u4E0D\u7528\u7070\u6D46\u780C\u6210\u7684\u65B0\u6708\u5F62\u77F3\u5899\uFF0C\u4F4D\u4E8E\u9E70\u5DE2\u57CE\u4E0B\u65B9\u7EA6\u516D\u767E\u5C3A\uFF1B\u6709\u4E00\u6761\u51FF\u6709\u6276\u624B\u7684\u5CA9\u7F1D\u901A\u9053\u53EF\u6500\u4E0A\u57CE\u5821\uFF0C\u7269\u8D44\u5219\u7531\u94C1\u94FE\u7EDE\u76D8\u540A\u7BEE\u8FD0\u9001\uFF1B\u82B1\u56ED\u539F\u60F3\u8F9F\u4F5C\u795E\u6728\u6797\uFF0C\u4F46\u571F\u5C42\u592A\u8584\uFF0C\u9C7C\u6881\u6728\u65E0\u6CD5\u751F\u957F\uFF0C\u56ED\u4E2D\u7ACB\u7740\u4E00\u5C0A\u54ED\u6CE3\u5973\u5B50\u7684\u77F3\u50CF\u3002\u9875\u9762\u672A\u6293\u53D6\u3002"}}],landmarks:{"the-vale":e(["The Vale","\u8C37\u5730"],["The fertile valley below, ringed by the Mountains of the Moon; when the weather turns, cloud fills it.","\u5C71\u4E0B\u80A5\u6C83\u7684\u8C37\u5730\uFF0C\u56DB\u5468\u660E\u6708\u5C71\u8109\u73AF\u62B1\uFF1B\u5929\u6C14\u4E00\u53D8\uFF0C\u4E91\u6D77\u4FBF\u6F2B\u6EE1\u8C37\u5E95\u3002"],["Far below the Eyrie lies the Vale, rich and sheltered.","\u9E70\u5DE2\u57CE\u811A\u4E0B\u8FDC\u5904\uFF0C\u662F\u5BCC\u9976\u800C\u5B89\u7A33\u7684\u8C37\u5730\u3002"],"high",["agot","twoiaf"],["A fertile valley enclosed by the Mountains of the Moon, with the Eyrie high above it.","\u88AB\u660E\u6708\u5C71\u8109\u73AF\u7ED5\u7684\u80A5\u6C83\u8C37\u5730\uFF0C\u9E70\u5DE2\u57CE\u9AD8\u8E1E\u5176\u4E0A\u3002"],["How the valley actually lies around this mountain.","\u8C37\u5730\u73AF\u7ED5\u6B64\u5C71\u7684\u771F\u5B9E\u683C\u5C40\u3002"],["A simple patchwork of fields and one lake stand in for the whole Vale.","\u4EE5\u7B80\u5316\u7684\u7530\u5757\u4E0E\u4E00\u5EA7\u6E56\u6CCA\u4EE3\u8868\u6574\u4E2A\u8C37\u5730\u3002"]),"gates-of-the-moon":e(["Gates of the Moon","\u6708\u95E8\u5821"],["A castle at the mountain's foot where the climb to the Eyrie begins.","\u5C71\u811A\u4E0B\u7684\u57CE\u5821\uFF0C\u6500\u767B\u9E70\u5DE2\u57CE\u7684\u65C5\u7A0B\u7531\u6B64\u5F00\u59CB\u3002"],["Everyone and everything bound for the Eyrie stops here first.","\u524D\u5F80\u9E70\u5DE2\u57CE\u7684\u4EBA\u548C\u7269\uFF0C\u90FD\u8981\u5148\u5728\u8FD9\u91CC\u843D\u811A\u3002"],"high",["agot","affc"],["A castle at the foot of the mountain where the road to the Eyrie begins; the household comes down to winter here.","\u4F4D\u4E8E\u5C71\u811A\u7684\u57CE\u5821\uFF0C\u901A\u5F80\u9E70\u5DE2\u57CE\u7684\u5C71\u8DEF\u7531\u6B64\u5F00\u59CB\uFF1B\u5165\u51AC\u540E\u57CE\u4E2D\u4E0A\u4E0B\u4F1A\u8FC1\u5230\u8FD9\u91CC\u8FC7\u51AC\u3002"],["Its plan and number of towers.","\u5E73\u9762\u4E0E\u5854\u697C\u6570\u91CF\u3002"],["A rectangular curtain wall, four towers and a keep are invented.","\u65B9\u5F62\u57CE\u5899\u3001\u56DB\u5EA7\u5854\u697C\u4E0E\u4E3B\u5821\u5747\u4E3A\u81EA\u62DF\u3002"]),"stone-waycastle":e(["Stone","\u77F3\u5821"],["The lowest waycastle on the mule path.","\u9AA1\u9053\u4E0A\u6700\u4F4E\u7684\u4E00\u5EA7\u8DEF\u5821\u3002"],["Stone, the first waycastle, guards the lower path.","\u7B2C\u4E00\u5EA7\u8DEF\u5821\u77F3\u5821\uFF0C\u5B88\u62A4\u7740\u5C71\u8DEF\u7684\u4E0B\u6BB5\u3002"],"medium",["agot","awoiaf"],["A waycastle called Stone is the first stop on the climb.","\u540D\u4E3A\u201C\u77F3\u5821\u201D\u7684\u8DEF\u5821\u662F\u6500\u767B\u9014\u4E2D\u7684\u7B2C\u4E00\u7AD9\u3002"],["Its form, size and height on the mountain.","\u5F62\u5236\u3001\u89C4\u6A21\u53CA\u6240\u5728\u9AD8\u5EA6\u3002"],["A gatehouse, a wall and two outbuildings, about a fifth of the way up.","\u95E8\u697C\u3001\u57CE\u5899\u4E0E\u4E24\u5EA7\u9644\u5C5E\u5EFA\u7B51\uFF0C\u8BBE\u5728\u7EA6\u4E94\u5206\u4E4B\u4E00\u5C71\u9AD8\u5904\u3002"]),"snow-waycastle":e(["Snow","\u96EA\u5821"],["The middle waycastle, set against the rock above the path.","\u4E2D\u6BB5\u7684\u8DEF\u5821\uFF0C\u501A\u7740\u5C71\u5CA9\uFF0C\u4FEF\u4E34\u5C71\u8DEF\u3002"],["Snow clings to the rock and watches the path below.","\u96EA\u5821\u7D27\u8D34\u5CA9\u58C1\uFF0C\u4FEF\u89C6\u4E0B\u65B9\u5C71\u8DEF\u3002"],"medium",["agot","awoiaf"],["A second waycastle, Snow, lies above Stone.","\u77F3\u5821\u4E4B\u4E0A\u662F\u7B2C\u4E8C\u5EA7\u8DEF\u5821\u96EA\u5821\u3002"],["Its form and altitude.","\u5F62\u5236\u4E0E\u6D77\u62D4\u3002"],["A square tower, a round tower and a hall at mid-height.","\u534A\u5C71\u8170\u4E00\u5EA7\u65B9\u5854\u3001\u4E00\u5EA7\u5706\u5854\u4E0E\u4E00\u5EA7\u5385\u5802\u3002"]),"sky-waycastle":e(["Sky","\u5929\u5821"],["The highest waycastle: a crescent wall of unmortared stone against the mountain, with its barracks cut into the rock. The Eyrie is some six hundred feet above.","\u6700\u9AD8\u7684\u4E00\u5EA7\u8DEF\u5821\uFF1A\u4E00\u9053\u4E0D\u7528\u7070\u6D46\u3001\u501A\u5C71\u800C\u780C\u7684\u65B0\u6708\u5F62\u77F3\u5899\uFF0C\u8425\u623F\u51FF\u5728\u5C71\u5CA9\u4E4B\u4E2D\u3002\u9E70\u5DE2\u57CE\u8FD8\u5728\u5176\u4E0A\u7EA6\u516D\u767E\u5C3A\u5904\u3002"],["From Sky, travellers climb the rock; supplies ride up in baskets.","\u5230\u4E86\u5929\u5821\uFF0C\u65C5\u4EBA\u987B\u6500\u5CA9\u800C\u4E0A\uFF0C\u7269\u8D44\u5219\u7528\u540A\u7BEE\u8FD0\u9001\u3002"],"high",["agot","awoiaf"],["Sky is the last waycastle. Above it, people climb a chimney with handholds cut in the stone, while winches in the Eyrie's cellars haul baskets on chains.","\u5929\u5821\u662F\u6700\u540E\u4E00\u5EA7\u8DEF\u5821\u3002\u518D\u5F80\u4E0A\uFF0C\u4EBA\u8981\u6CBF\u7740\u51FF\u6709\u6276\u624B\u7684\u5CA9\u7F1D\u6500\u722C\uFF0C\u7269\u8D44\u5219\u7531\u9E70\u5DE2\u57CE\u5730\u7A96\u91CC\u7684\u7EDE\u76D8\u4EE5\u94C1\u94FE\u540A\u7BEE\u8FD0\u4E0A\u53BB\u3002"],["The exact course of the chimney and the winch arrangement.","\u5CA9\u7F1D\u901A\u9053\u7684\u786E\u5207\u8D70\u5411\u4E0E\u7EDE\u76D8\u7684\u5E03\u7F6E\u3002"],["A basket on a rope runs between Sky and the Eyrie; the free-standing timber frame is invented.","\u4E00\u53EA\u540A\u7BEE\u6CBF\u7EF3\u5F80\u8FD4\u4E8E\u5929\u5821\u4E0E\u9E70\u5DE2\u57CE\u4E4B\u95F4\uFF1B\u9732\u5929\u6728\u67B6\u4E3A\u81EA\u62DF\u3002"]),"alyssas-tears":e(["Alyssa's Tears","\u827E\u4E3D\u838E\u4E4B\u6CEA"],["A waterfall that leaps from the mountain and turns to mist before it ever reaches the valley.","\u4E00\u9053\u81EA\u5C71\u95F4\u98DE\u6CFB\u7684\u7011\u5E03\uFF0C\u8FD8\u6CA1\u843D\u5230\u8C37\u5E95\u4FBF\u5316\u4F5C\u6C34\u96FE\u3002"],["Legend says not one of Alyssa's tears has ever reached the ground.","\u4F20\u8BF4\u827E\u4E3D\u838E\u4E4B\u6CEA\u4ECE\u672A\u6709\u4E00\u6EF4\u843D\u5230\u5730\u9762\u3002"],"high",["agot","twoiaf"],["A waterfall named for Alyssa Arryn, who shed no tears in life; it vanishes into mist before reaching the Vale.","\u4EE5\u827E\u4E3D\u838E\xB7\u827E\u6797\u547D\u540D\u7684\u7011\u5E03\uFF1B\u76F8\u4F20\u5979\u751F\u524D\u4ECE\u672A\u843D\u6CEA\uFF0C\u8FD9\u9053\u7011\u5E03\u4E5F\u603B\u5728\u843D\u5230\u8C37\u5E95\u524D\u6D88\u6563\u6210\u96FE\u3002"],["The water's exact course and source.","\u6C34\u6D41\u7684\u786E\u5207\u8DEF\u5F84\u4E0E\u6E90\u5934\u3002"],["A single ribbon on the western shoulder with mist at its foot.","\u897F\u4FA7\u5C71\u80A9\u4E0A\u4E00\u9053\u7EC6\u957F\u6C34\u5E26\uFF0C\u4E0B\u65B9\u6C34\u96FE\u5F25\u6F2B\u3002"]),"giants-lance":e(["Giant's Lance","\u5DE8\u4EBA\u4E4B\u67AA"],["The tall peak behind the Eyrie, snow-capped and often lost in cloud.","\u9E70\u5DE2\u57CE\u80CC\u540E\u7684\u9AD8\u5CF0\uFF0C\u5CF0\u9876\u79EF\u96EA\uFF0C\u5E38\u9690\u6CA1\u5728\u4E91\u4E2D\u3002"],["The Giant's Lance dwarfs the Eyrie, which sits only on its shoulder.","\u5DE8\u4EBA\u4E4B\u67AA\u8FDC\u6BD4\u9E70\u5DE2\u57CE\u9AD8\u5927\uFF0C\u57CE\u5821\u4E0D\u8FC7\u501A\u5728\u5B83\u7684\u5C71\u80A9\u4E0A\u3002"],"high",["agot","twoiaf"],["The Eyrie is built on a shoulder of the mountain called the Giant's Lance.","\u9E70\u5DE2\u57CE\u5EFA\u5728\u5DE8\u4EBA\u4E4B\u67AA\u7684\u5C71\u80A9\u4E0A\u3002"],["The peak's true height and shape.","\u5C71\u5CF0\u7684\u771F\u5B9E\u9AD8\u5EA6\u4E0E\u5F62\u72B6\u3002"],["An exaggerated spire; the scale is symbolic.","\u523B\u610F\u5938\u5F20\u7684\u5C16\u5CF0\uFF0C\u5C3A\u5EA6\u53EA\u5177\u8C61\u5F81\u610F\u4E49\u3002"]),"eyrie-towers":e(["The Eyrie","\u9E70\u5DE2\u57CE"],["A small castle of white stone: seven slender towers bunched together like arrows in a quiver.","\u767D\u77F3\u780C\u6210\u7684\u5C0F\u57CE\u5821\uFF1A\u4E03\u5EA7\u7EC6\u9AD8\u7684\u5854\u697C\u7D27\u7D27\u7C07\u62E5\uFF0C\u5B9B\u5982\u7BAD\u56CA\u4E2D\u7684\u4E00\u675F\u7BAD\u3002"],["Seven white towers, small as a toy against the mountain.","\u4E03\u5EA7\u767D\u5854\uFF0C\u5728\u5927\u5C71\u9762\u524D\u5C0F\u5982\u73A9\u5177\u3002"],"high",["agot","asos"],["A small castle of white stone with seven slender towers, built on a shoulder of the mountain.","\u767D\u77F3\u5C0F\u57CE\uFF0C\u6709\u4E03\u5EA7\u7EC6\u9AD8\u5854\u697C\uFF0C\u5EFA\u5728\u5C71\u80A9\u4E4B\u4E0A\u3002"],["The towers' heights and the inner layout.","\u5404\u5854\u9AD8\u5EA6\u4E0E\u5185\u90E8\u5E03\u5C40\u3002"],["The ring of seven towers and the low outer wall are one reading of the text.","\u4E03\u5854\u6210\u73AF\u4E0E\u4F4E\u77EE\u5916\u5899\uFF0C\u662F\u5BF9\u539F\u6587\u7684\u4E00\u79CD\u89E3\u8BFB\u3002"]),"high-hall":e(["High Hall","\u9AD8\u5385"],["A long hall of milk-white marble veined with blue, with tall windows and slender pillars. A cutaway shows it.","\u4E73\u767D\u8272\u3001\u5E26\u84DD\u8272\u7EB9\u7406\u7684\u5927\u7406\u77F3\u780C\u6210\u7684\u957F\u5385\uFF0C\u9AD8\u7A97\u4FEE\u957F\uFF0C\u7EC6\u67F1\u6797\u7ACB\u3002\u53EF\u6253\u5F00\u5256\u9762\u67E5\u770B\u3002"],["The High Hall is cold and austere, a place of judgment.","\u9AD8\u5385\u6E05\u51B7\u8083\u7A46\uFF0C\u662F\u5BA1\u5224\u4E4B\u6240\u3002"],"high",["agot","asos"],["A long hall of pale, blue-veined marble where the lord of the Eyrie holds court and judgment; the Moon Door is in its wall.","\u4EE5\u5E26\u84DD\u7EB9\u7684\u6D45\u8272\u5927\u7406\u77F3\u780C\u6210\u7684\u957F\u5385\uFF0C\u9E70\u5DE2\u57CE\u4E3B\u5728\u6B64\u8BAE\u4E8B\u3001\u5BA1\u5224\uFF1B\u6708\u95E8\u5C31\u5F00\u5728\u5385\u5899\u4E0A\u3002"],["Its dimensions, windows and seating.","\u5C3A\u5BF8\u3001\u7A97\u6237\u4E0E\u5EA7\u5E2D\u3002"],["The columns, tall windows, long table and dais are invented.","\u7ACB\u67F1\u3001\u9AD8\u7A97\u3001\u957F\u684C\u4E0E\u9AD8\u53F0\u5747\u4E3A\u81EA\u62DF\u3002"]),"moon-door":e(["Moon Door","\u6708\u95E8"],["A narrow weirwood door in the High Hall that opens onto empty air; the condemned go out through it.","\u9AD8\u5385\u91CC\u4E00\u6247\u7A84\u7A84\u7684\u9C7C\u6881\u6728\u95E8\uFF0C\u95E8\u5916\u5373\u662F\u865A\u7A7A\uFF1B\u88AB\u5224\u6B7B\u5211\u8005\u4FBF\u7531\u6B64\u88AB\u63A8\u51FA\u3002"],["One narrow door, and beyond it nothing but sky and a long fall.","\u4E00\u6247\u7A84\u95E8\u4E4B\u5916\uFF0C\u53EA\u6709\u5929\u7A7A\u4E0E\u6DF1\u4E0D\u89C1\u5E95\u7684\u5760\u843D\u3002"],"high",["agot","asos"],["A weirwood door in the High Hall opening on a sheer drop, used for executions.","\u9AD8\u5385\u4E2D\u4E00\u6247\u5F00\u5411\u7EDD\u58C1\u7684\u9C7C\u6881\u6728\u95E8\uFF0C\u7528\u4E8E\u5904\u51B3\u3002"],["Its exact position and the height of the drop.","\u786E\u5207\u4F4D\u7F6E\u4E0E\u4E0B\u5760\u9AD8\u5EA6\u3002"],["A pale door in the hall's west wall, with a narrow stone sill outside.","\u5385\u5802\u897F\u5899\u4E0A\u4E00\u6247\u6D45\u8272\u7684\u95E8\uFF0C\u95E8\u5916\u6709\u4E00\u9053\u7A84\u7A84\u7684\u77F3\u69DB\u3002"],["In the third book a key scene of the Vale story ends at this door.","\u7B2C\u4E09\u5377\u4E2D\uFF0C\u8C37\u5730\u6545\u4E8B\u7684\u4E00\u573A\u5173\u952E\u620F\u5C31\u5728\u8FD9\u6247\u95E8\u524D\u6536\u573A\u3002"]),"sky-cells":e(["Sky Cells","\u5929\u7262"],["Cells with one side open to the sky and floors that slope toward the drop.","\u4E00\u9762\u671D\u5929\u655E\u5F00\u3001\u5730\u9762\u5411\u60AC\u5D16\u503E\u659C\u7684\u7262\u623F\u3002"],["The Eyrie's cells have no fourth wall, and the floor slopes toward the edge.","\u9E70\u5DE2\u57CE\u7684\u7262\u623F\u5C11\u4E86\u4E00\u9762\u5899\uFF0C\u5730\u9762\u8FD8\u5411\u5D16\u8FB9\u503E\u659C\u3002"],"high",["agot"],["Cells open to the sky on one side, their floors sloping toward the edge; a prisoner is held in one in the first book.","\u4E00\u9762\u5411\u5929\u655E\u5F00\u3001\u5730\u9762\u5411\u5D16\u8FB9\u503E\u659C\u7684\u7262\u623F\uFF1B\u7B2C\u4E00\u5377\u4E2D\u66FE\u6709\u4E00\u540D\u56DA\u72AF\u88AB\u5173\u5728\u8FD9\u91CC\u3002"],["How many there are and exactly where.","\u6570\u91CF\u4E0E\u786E\u5207\u4F4D\u7F6E\u3002"],["Three ledges on the eastern cliff.","\u4E1C\u4FA7\u5D16\u58C1\u4E0A\u7684\u4E09\u5C42\u5CA9\u53F0\u3002"]),"eyrie-godswood":e(["Garden & Godswood","\u82B1\u56ED\u4E0E\u795E\u6728\u6797"],["A small garden at the castle's heart, planted as a godswood; the soil is too thin for a weirwood, so grass, shrubs and a statue of a weeping woman fill it instead.","\u57CE\u5821\u4E2D\u5FC3\u7684\u4E00\u5EA7\u5C0F\u82B1\u56ED\uFF0C\u672C\u60F3\u8F9F\u4F5C\u795E\u6728\u6797\uFF0C\u4F46\u571F\u5C42\u592A\u8584\uFF0C\u9C7C\u6881\u6728\u79CD\u4E0D\u6D3B\uFF0C\u56ED\u4E2D\u53EA\u6709\u8349\u5730\u3001\u704C\u6728\u548C\u4E00\u5C0A\u54ED\u6CE3\u5973\u5B50\u7684\u77F3\u50CF\u3002"],["The Eyrie's godswood has no weirwood: the mountain will not let one grow.","\u9E70\u5DE2\u57CE\u7684\u795E\u6728\u6797\u91CC\u6CA1\u6709\u9C7C\u6881\u6728\uFF1A\u8FD9\u5EA7\u5C71\u5BB9\u4E0D\u4E0B\u5B83\u751F\u957F\u3002"],"medium",["agot","asos","awoiaf"],["A garden meant as a godswood, where no weirwood would take root; a marble statue of a weeping woman, thought to be Alyssa Arryn, stands at its centre.","\u539F\u60F3\u8F9F\u4F5C\u795E\u6728\u6797\u7684\u82B1\u56ED\uFF0C\u9C7C\u6881\u6728\u59CB\u7EC8\u65E0\u6CD5\u624E\u6839\uFF1B\u56ED\u4E2D\u592E\u7ACB\u7740\u4E00\u5C0A\u54ED\u6CE3\u5973\u5B50\u7684\u5927\u7406\u77F3\u50CF\uFF0C\u4E00\u822C\u8BA4\u4E3A\u662F\u827E\u4E3D\u838E\xB7\u827E\u6797\u3002"],["Its exact size and position.","\u786E\u5207\u5927\u5C0F\u4E0E\u4F4D\u7F6E\u3002"],["The scene's weirwood is an artistic liberty: the books say none grows here.","\u573A\u666F\u4E2D\u7684\u9C7C\u6881\u6728\u5C5E\u4E8E\u827A\u672F\u52A0\u5DE5\uFF1A\u4E66\u4E2D\u660E\u8A00\u6B64\u5904\u6CA1\u6709\u9C7C\u6881\u6728\u3002"],["The statue is broken in a fight in the first book; in the third it lies half buried in snow.","\u7B2C\u4E00\u5377\u7684\u4E00\u573A\u51B3\u6597\u4E2D\u77F3\u50CF\u88AB\u63A8\u5012\u6454\u788E\uFF1B\u5230\u7B2C\u4E09\u5377\uFF0C\u5B83\u534A\u57CB\u5728\u79EF\u96EA\u4E4B\u4E2D\u3002"])}};export{d as default};
